{
  "probability": 0.11,
  "range_low": 0.07,
  "range_high": 0.16,
  "summary": [
    "Anchor probability from historical likelihood of a two-thirds majority in Hungary (~0.44) as baseline.",
    "Current polling fragmentation and large undecided share push the chance downward.",
    "Opposition consolidation behind TISZA increases anti-Fidesz vote share but makes a clean 2/3 unlikely; tail scenarios exist via seat-projection models.",
    "Overall calibrated posterior: 0.11 with broad uncertainty about turnout and seat translation."
  ],
  "confidence": "low",
  "narrative": "Starting from a historical anchor of ~0.44 for a 2/3 majority, updates from polling divergence, turnout volatility, and system biases pull the probability downward. The mixed evidence suggests tail-risk scenarios but the overall picture remains modest around 11%.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical probability that any party or coalition achieves a two-thirds majority (133 of 199 seats) in Hungary's National Assembly since 1990; four of nine elections produced a 2/3 majority, giving a rough anchor near 0.44."
    },
    "factor_updates": [
      {
        "factor": "Polling divergence and undecided-voter dynamics",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Polls split between Fidesz and TISZA with sizable undecideds; this uncertainty tends to erode a stable 2/3 majority path."
      },
      {
        "factor": "Opposition consolidation behind TISZA",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Consolidation around a single anti-Fidesz candidate reduces Fidesz vote aggregation but makes a unified 2/3 for one actor unlikely; however it raises the chance of a non-Fidesz coalition, which is not captured by a single-party 2/3 metric."
      },
      {
        "factor": "Seat-projection variability and near-2/3 scenarios",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Certain seat-projection models show near-2/3 outcomes under favorable margins; this keeps a non-negligible tail risk alive for 2/3, even if mainstream forecasts don’t imply it."
      },
      {
        "factor": "Historical precedent for 2/3 majorities",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Past occurrences prove 2/3 is possible; serves as a light up-weight to the posterior, though not conclusive for the current cycle."
      },
      {
        "factor": "Market expectations signaling regime change",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Financial markets price in non-Fidesz outcomes; this enhances perceived probability of non-2/3 paths via coalitions."
      },
      {
        "factor": "Electoral-system translation effects under Hungary's mixed system",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The mixed system makes translating votes to seats uneven; even large vote shares may fail to deliver 2/3, depressing the single-actor probability."
      }
    ],
    "synthesis_rationale": "Starting from the anchor, the updates are applied in sequence reflecting their directional impact. The dominant forces are structural biases and polling divergence that push the probability downward, offset slightly by tail risks from seat projections and occasional pro-coalition signals. The net effect yields a calibrated low posterior (11%), with a wide interval to account for turnout and translation uncertainties."
  }
}

{
  "probability": 0.11,
  "range_low": 0.08,
  "range_high": 0.14,
  "summary": [
    "Bayesian posterior probability for a 2/3 majority in 2026 Hungary is 11%.",
    "Forecasts are highly split; no single party dominates in polls, and seat projections do not show a clean 133-seat path.",
    "Opposition consolidation around TISZA reduces Fidesz's odds but the electoral system's bias toward the largest bloc keeps a 2/3 outcome as a tail risk.",
    "Turnout and undecided-voter dynamics maintain substantial upside/downside risks."
  ],
  "confidence": "low",
  "narrative": "The case-specific posterior places the odds of a 2/3 majority at about 11%, reflecting fragmented polling and imperfect translation of votes to seats under Hungary's system. While tail risks exist, the balance of evidence suggests a low probability for a single party or formal coalition to reach 133 seats this cycle.",
  "justification": {
    "anchor": {
      "probability": 0.15,
      "basis": "Reference-class starting point based on historical frequency of 2/3 majorities and the current highly fragmented polling landscape prior to updates."
    },
    "factor_updates": [
      {
        "factor": "Polling divergence and undecided-voter dynamics",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls and sizable undecided shares reduce confidence that any actor will hit 133 seats, yielding downward adjustment from the anchor."
      },
      {
        "factor": "Opposition consolidation behind TISZA",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Consolidation around a single opposition candidate reduces fragmentation but does not guarantee a 2/3 outcome, contributing to the downward shift."
      },
      {
        "factor": "Seat-projection variability and near-2/3 scenarios",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Some models show near-2/3 possibilities, introducing a tail risk that prevents a pure downward drift."
      },
      {
        "factor": "Historical precedent for 2/3 majorities",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Past occurrences confirm the possibility of a 2/3 outcome, providing a small upward bias."
      },
      {
        "factor": "Electoral-system translation effects under Hungary's mixed system",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "The mixed system distorts vote shares into seats, making a 2/3 majority less likely even with strong vote shares."
      }
    ],
    "synthesis_rationale": "Starting from a 0.15 anchor, the updates from polling fragmentation, opposition consolidation, and system translation push the posterior toward 0.11, with tail-risk models and historical precedent offering modest upward pressure. The final estimate reflects case-specific uncertainties around turnout and district-level translations, resulting in a calibrated 11% probability."
  }
}

{
  "probability": 0.29,
  "range_low": 0.20,
  "range_high": 0.40,
  "summary": [
    "Opposition consolidation behind TISZA increases non-Fidesz odds, but unlikely to produce a 2/3 majority by itself.",
    "Hungary's mixed-member majoritarian system and the 133-seat hurdle create structural headwinds that complicate reaching 2/3 even with strong polling.",
    "Polls are divergent and a sizable share remains undecided, suggesting further volatility and risk to both sides.",
    "Overall probability anchored near historical 44% is adjusted downward to around 29%, with tail risk if a broader anti-Fidesz coalition forms."
  ],
  "confidence": "medium",
  "narrative": "Starting from a baseline near 44% based on historical outcomes, current polling fragmentation and structural biases tilt the odds downward. The strongest counter case is potential anti-Fidesz coalition success via TISZA, but turnout and translation effects keep the probability around 29% with a wide uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.44,
      "basis": "Historical probability that any party or coalition achieves a two-thirds majority (133 of 199 seats) in post-1990 Hungary; four of nine elections produced a 2/3 majority (~44%)."
    },
    "factor_updates": [
      {
        "factor": "Opposition consolidation behind TISZA",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "FT reports opposition groups consolidating behind TISZA; polls show TISZA ahead, increasing anti-Fidesz vote share and potentially enabling a 2/3 coalition."
      },
      {
        "factor": "Structural bias of Hungary's mixed-member majoritarian system",
        "direction": "down",
        "magnitude": "strong",
        "rationale": "System tends to reward the largest party and makes 133-seat majority difficult; seat projections show no path to 2/3 for any single actor without extreme margins."
      },
      {
        "factor": "Polling divergence and undecided voters",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Divergent polls and sizable undecided share reduce confidence that any side can consolidate 2/3, complicating translation to seats."
      },
      {
        "factor": "Turnout volatility and undecided-voter risk",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Turnout swings and undecided voters create uncertainty about final seat distribution and 2/3 chances."
      },
      {
        "factor": "Third-party fragmentation risk crossing threshold",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Other minor parties crossing the 5% threshold could siphon anti-Fidesz votes and complicate a 2/3 outcome for any coalition."
      },
      {
        "factor": "Market expectations signaling regime change",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Markets pricing regime-change if opposition leads could reflect expected non-2/3 path for incumbents and slight tilt toward non-Fidesz outcomes, but is not a direct predictor of seat totals."
      }
    ],
    "synthesis_rationale": "The final probability starts from the 44% anchor and applies additive updates with moderate weights for opposition consolidation and market signals, balanced against strong negative pressure from structural bias and polling/turnout uncertainties. The net effect places the forecast around 0.29 with a 0.20–0.40 range, reflecting significant but not decisive uncertainty and the possibility of tail scenarios if the opposition unites and turnout favors them."
  }
}
